class BowlingGame:
    def __init__(self):
        self.rolls = []
        self._frame = 0
        self._pins = 0
        self._rolls_in_frame = 0
        self._tenth_start = None

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise Exception("pins must be between 0 and 10")
        if self._frame == 10:
            raise Exception("cannot roll after game is over")
        if self._frame < 9:
            if self._pins + pins > 10:
                raise Exception("two rolls in a frame cannot score more than 10 points")
            self._pins += pins
            self._rolls_in_frame += 1
            self.rolls.append(pins)
            if self._pins == 10 or self._rolls_in_frame == 2:
                self._frame += 1
                self._pins = 0
                self._rolls_in_frame = 0
                if self._frame == 9:
                    self._tenth_start = len(self.rolls)
        else:
            tenth = self.rolls[self._tenth_start:]
            if len(tenth) == 1:
                if tenth[0] != 10 and tenth[0] + pins > 10:
                    raise Exception("two rolls in a frame cannot score more than 10 points")
            elif len(tenth) == 2:
                if tenth[0] == 10:
                    if tenth[1] != 10 and tenth[1] + pins > 10:
                        raise Exception("bonus rolls cannot score more than 10 points")
                elif tenth[0] + tenth[1] < 10:
                    raise Exception("cannot roll after an open frame")
            self.rolls.append(pins)
            tenth = self.rolls[self._tenth_start:]
            if len(tenth) == 3 or (len(tenth) == 2 and tenth[0] + tenth[1] < 10):
                self._frame = 10

    def score(self):
        if self._frame < 10:
            raise Exception("cannot score an incomplete game")
        total = 0
        i = 0
        while i < self._tenth_start:
            if self.rolls[i] == 10:
                total += 10 + self.rolls[i + 1] + self.rolls[i + 2]
                i += 1
            elif self.rolls[i] + self.rolls[i + 1] == 10:
                total += 10 + self.rolls[i + 2]
                i += 2
            else:
                total += self.rolls[i] + self.rolls[i + 1]
                i += 2
        total += sum(self.rolls[self._tenth_start:])
        return total
